WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-HI-005', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_mental_health_parity', 'federal + state', 'federal + state -- ALL_STATES', 'Mental Health Parity -- The Comparative Analysis the Plan Must Give You', 'federal_agency | state_regulator', 'healthcare_mental_health_parity', 'https://www.dol.gov/agencies/ebsa/laws-and-regulations/laws/mental-health-and-substance-use-disorder-parity', 'DOL Employee Benefits Security Administration: 866-444-3272 | 988 Suicide and Crisis Lifeline | Your state Department of Insurance', 'Mental Health Parity and Addiction Equity Act (29 U.S.C. sec. 1185a; 42 U.S.C. sec. 300gg-26) | Comparative analysis requirement (Consolidated Appropriations Act 2021) | 45 CFR 146.136; 29 CFR 2590.712 | State parity and network adequacy statutes.', 'VERIFIED', '2026-08-17', 'REQUEST THE PLAN''S NON-QUANTITATIVE TREATMENT LIMITATION COMPARATIVE ANALYSIS IN WRITING AND APPEAL ON PARITY GROUNDS IN ADDITION TO MEDICAL NECESSITY. This is the most powerful and least used tool in behavioral health coverage. A plan that cannot produce an adequate comparative analysis has a documented compliance problem, and that fact belongs in the external review request and in the regulator complaint filed alongside it. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: b4483f158b6e5f57a99de74cb89154f67d1bbcf0e0e6223d81e551f104677939]', 'v1.0'),
('SAIS-HI-006', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_substance_abuse_treatment', 'federal + state', 'federal + state -- ALL_STATES', 'Substance Use Disorder Treatment -- Access Barriers and Confidentiality Protections', 'federal_agency | state_agency', 'healthcare_substance_abuse_treatment', 'https://findtreatment.gov/', 'SAMHSA National Helpline: 800-662-4357 (free, confidential, 24/7, English and Spanish) | 988 Suicide and Crisis Lifeline | Your state substance use agency', 'Mental Health Parity and Addiction Equity Act (29 U.S.C. sec. 1185a) | 42 CFR Part 2 (confidentiality of SUD patient records) | 42 U.S.C. sec. 290dd-2 | SUPPORT Act | State SUD coverage mandate statutes.', 'VERIFIED', '2026-08-17', 'APPEAL ON PARITY GROUNDS, NOT ONLY MEDICAL NECESSITY, AND REQUEST EXPEDITED REVIEW BY NAME. Prior authorization and fail-first requirements applied to SUD treatment but not to comparable medical care are the most common and most challengeable barriers. The SAMHSA National Helpline (800-662-4357) is free, confidential, and available at any hour regardless of coverage, and it is the correct immediate step while a coverage fight proceeds in parallel. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ae91bb5cd978e6dcad430533f2cb76c30f7e26ffdac155e223766a46c4b665b2]', 'v1.0'),
('SAIS-HI-007', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_clinical_trial_harm', 'federal', 'federal -- NATIONWIDE', 'Clinical Trial Harm -- Consent Documents, the IRB, and Who Pays for Injury', 'federal_agency | institutional_review_board', 'healthcare_clinical_trial_harm', 'https://www.hhs.gov/ohrp/', 'HHS Office for Human Research Protections: 866-447-4777 | FDA Office of Good Clinical Practice | The study''s IRB (named in the consent form)', 'Federal Policy for the Protection of Human Subjects, the Common Rule (45 CFR Part 46) | FDA human subject protection regulations (21 CFR Parts 50 and 56) | Informed consent elements (45 CFR 46.116) | IRB authority to suspend or terminate (45 CFR 46.113)', 'VERIFIED', '2026-08-17', 'REQUEST THE SIGNED CONSENT FORM, THE IRB-APPROVED PROTOCOL, AND ANY PROTOCOL AMENDMENTS. The gap between the approved protocol and what actually occurred is the substance of most research complaints, and participants rarely have copies. The IRB, OHRP, and FDA complaint routes cost nothing, require no attorney, and can suspend a study -- they operate on a different track and a different timeline from any civil claim. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 484aba2d487c5728b5f13dede1d95af5e83b428916978de9d1e670ca7054e8e0]', 'v1.0'),
('SAIS-HI-008', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_telemedicine_malpractice', 'state', 'state -- ALL_STATES', 'Telemedicine Malpractice -- Same Standard of Care, Different Evidence Problems', 'state_licensing_board | state_court', 'healthcare_telemedicine_malpractice', 'https://www.fsmb.org/contact-a-state-medical-board/', 'Your state medical board -- see jurisdiction table | Federation of State Medical Boards | HHS Office for Civil Rights: 800-368-1019', 'State medical practice acts and telehealth statutes | Interstate Medical Licensure Compact | Ryan Haight Act (21 U.S.C. sec. 829(e)) for controlled substance prescribing | HIPAA right of access (45 CFR 164.524) | State malpractice procedural statutes.', 'VERIFIED', '2026-08-17', 'ESTABLISH WHERE THE PATIENT WAS PHYSICALLY LOCATED DURING THE ENCOUNTER AND REQUEST THE PLATFORM SESSION METADATA IMMEDIATELY. Patient location determines licensure, governing law, and limitations period; session metadata determines whether the documented encounter actually occurred as recorded, and it is deleted on retention schedules far shorter than medical records. Both are free to request and both are routinely never requested. [address_resolution: Resolve via the state board''s published office address; single statewide location in most states. Input = state only.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: abcb816dd37151b74f3a2f774788e3706e238cff83d7ab7f145224e66042771a]', 'v1.0'),
('SAIS-HI-009', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_dental_malpractice', 'state', 'state -- ALL_STATES', 'Dental Malpractice -- Records, Radiographs, and the Dental Board Track', 'state_licensing_board | state_court', 'healthcare_dental_malpractice', 'https://www.hhs.gov/hipaa/for-individuals/medical-records/index.html', 'Your state Board of Dental Examiners -- see jurisdiction table | HHS Office for Civil Rights (records access): 800-368-1019', 'HIPAA right of access (45 CFR 164.524) | State dental practice acts | State malpractice certificate-of-merit and pre-suit notice statutes | National Practitioner Data Bank (42 U.S.C. sec. 11101 et seq.)', 'VERIFIED', '2026-08-17', 'REQUEST ALL RADIOGRAPHS IN DIAGNOSTIC FORMAT, NOT SCREENSHOTS, AND REQUEST THE FULL SERIES INCLUDING PRIOR YEARS. A radiographic series is objective, dated, and frequently establishes progression that the treatment notes do not mention. Records access is a standalone HIPAA right enforceable through HHS Office for Civil Rights and is not conditioned on paying an outstanding balance or on refraining from a claim. [address_resolution: Resolve via the state board''s published office address; single statewide location in most states. Input = state only.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ff6df070c49119c2fe4cddf587f3e5f71759f286f7e9ad75bf1355cf12c9f304]', 'v1.0'),
('SAIS-HI-010', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_nursing_malpractice', 'federal + state', 'federal + state -- ALL_STATES', 'Nursing Malpractice -- Staffing Records, Charting Gaps, and Facility Accountability', 'state_licensing_board | state_agency | federal_agency', 'healthcare_nursing_malpractice', 'https://www.ncsbn.org/contact-bon.htm', 'Your state Board of Nursing -- see jurisdiction table | State health facility survey agency | Long-Term Care Ombudsman: 800-677-1116', 'HIPAA right of access (45 CFR 164.524) | Nursing Home Reform Act (42 U.S.C. sec. 1395i-3, 1396r) | Federal nursing facility requirements (42 CFR Part 483) | State nurse practice acts | State facility licensing statutes.', 'VERIFIED', '2026-08-17', 'REQUEST THE STAFFING AND ASSIGNMENT RECORDS AND THE ELECTRONIC RECORD AUDIT TRAIL, NOT JUST THE CHART. These two documents convert an individual charting failure into a documented facility condition, and they are retained on shorter schedules than the medical record. Send the preservation letter the same week. File the state survey agency complaint in parallel -- survey findings are public, free to obtain, and independently establish the facility''s prior notice. [address_resolution: Resolve via the state board''s published office address; single statewide location in most states. Input = state only.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 50af70415a653cfed8591a9c0469f5bbad8a9631a0f99027804932fe88f33e03]', 'v1.0'),
('SAIS-HI-011', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_ambulance_billing', 'federal + state', 'federal + state -- ALL_STATES', 'Ambulance Billing -- Where the No Surprises Act Applies and Where It Does Not', 'federal_agency | state_regulator', 'healthcare_ambulance_billing', 'https://www.cms.gov/nosurprises', 'No Surprises Help Desk: 800-985-3059 | Your state Department of Insurance -- see jurisdiction table | CMS: 800-633-4227', 'No Surprises Act (42 U.S.C. sec. 300gg-111 et seq.; air ambulance at sec. 300gg-112) | Prudent layperson emergency standard (42 U.S.C. sec. 300gg-111(a)) | EMTALA (42 U.S.C. sec. 1395dd) | State ground ambulance balance billing statutes.', 'VERIFIED', '2026-08-17', 'CHECK WHETHER YOUR STATE HAS ITS OWN GROUND AMBULANCE BALANCE BILLING PROTECTION -- federal law generally does not cover ground ambulance, and this gap is the source of most ambulance bills. Separately, appeal any ''not medically necessary'' denial of emergency transport under the PRUDENT LAYPERSON standard: the test is what a reasonable person believed at the time, not what the final diagnosis turned out to be, and insurers apply the wrong test routinely. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 31fcbd5601556e50e1985525f5468b419bc84a4563d4293653050397acea7aae]', 'v1.0'),
('SAIS-HI-012', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_prior_authorization_denial', 'federal + state', 'federal + state -- ALL_STATES', 'Prior Authorization Denial -- Peer-to-Peer Review and the Continuity-of-Care Right', 'federal_agency | state_regulator', 'healthcare_prior_authorization_denial', 'https://www.medicare.gov/claims-appeals', 'DOL Employee Benefits Security Administration: 866-444-3272 | Medicare: 800-633-4227 | Your state Department of Insurance | Your state SHIP program', 'ERISA claims procedure (29 CFR 2560.503-1) | ACA appeals and external review (45 CFR 147.136) | Medicare Advantage organization determinations and appeals (42 CFR Part 422 Subpart M) | Medicaid fair hearing and continuation of benefits (42 CFR 431.230) | State prior authorization reform statutes.', 'VERIFIED', '2026-08-17', 'ASK FOR THE PEER-TO-PEER REVIEW FIRST AND THE SPECIFIC CRITERIA IN WRITING. Peer-to-peer resolves a large share of denials in days without a formal appeal, and it does not consume the appeal deadline. For Medicaid: requesting a fair hearing within the continuation window -- commonly 10 DAYS -- keeps an existing service in place during the appeal, and that window is stated in fine print on a notice that reads like a form letter. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 5b65b7a132261ca6b348d098d67d4071db9d37e07ddaadf11e3019a6130fc50a]', 'v1.0'),
('SAIS-PC-001', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_insurance_claim_denial', 'federal + state', 'federal + state -- ALL_STATES', 'Insurance Claim Denial -- The Two-Stage Appeal Right Most People Never Use', 'federal_agency | state_regulator', 'personal_crisis_insurance_claim_denial', 'https://www.dol.gov/agencies/ebsa/about-ebsa/ask-a-question/ask-ebsa', 'DOL Employee Benefits Security Administration: 866-444-3272 | Your state Department of Insurance -- see jurisdiction table below', 'ERISA (29 U.S.C. sec. 1001 et seq.) | Claims procedure rule (29 CFR 2560.503-1) | ACA internal appeals and external review (42 U.S.C. sec. 300gg-19; 45 CFR 147.136) | McCarran-Ferguson Act (15 U.S.C. sec. 1011)', 'VERIFIED', '2026-08-17', 'REQUEST THE COMPLETE CLAIM FILE IN WRITING BEFORE YOU DRAFT THE APPEAL. Under the ERISA claims rule the plan must provide it free of charge, including the internal criteria applied. Appeals written without the claim file argue against a rationale the appellant is guessing at. Also file a parallel complaint with your state Department of Insurance -- regulator complaints are separately tracked and frequently produce movement the appeal alone does not. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 00caaeb277ded2fa546fa9bebd9b7062b3c2b7925db82ec7f66981bb854b6787]', 'v1.0'),
('SAIS-PC-002', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_tenant_rights_housing', 'federal + state', 'federal + state -- ALL_STATES', 'Tenant Rights and Housing -- Conditions, Retaliation, and the Eviction Clock', 'federal_agency | state_court | legal_aid', 'personal_crisis_tenant_rights_housing', 'https://www.hud.gov/topics/rental_assistance/tenantrights', 'HUD Housing Discrimination Hotline: 800-669-9777 | HUD-approved housing counseling: 800-569-4287 | Dial 211 for local tenant services', 'Fair Housing Act (42 U.S.C. sec. 3601 et seq.) | Section 504, Rehabilitation Act (29 U.S.C. sec. 794) | ADA Title II/III (42 U.S.C. sec. 12131, 12181) | State landlord-tenant acts and implied warranty of habitability.', 'VERIFIED', '2026-08-17', 'NEVER STOP PAYING RENT WITHOUT A SPECIFIC STATUTORY BASIS AND USUALLY WITHOUT DEPOSITING THE RENT WITH THE COURT. Self-help rent withholding is lawful in some states and is a fast route to eviction in others. Ask a local legal aid office which rule applies in your state BEFORE withholding. Also: a reasonable accommodation request under fair housing law can be made at any point, including after an eviction case has been filed, and a landlord''s refusal to consider one is itself a violation. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 849844eda1776718fb102bf6765db8cd5cd56f752141ff3dcb388950ebd0704d]', 'v1.0'),
('SAIS-PC-003', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_medical_malpractice', 'state', 'state -- ALL_STATES', 'Medical Malpractice -- The Procedural Gates Before the Claim', 'state_court | state_licensing_board', 'personal_crisis_medical_malpractice', 'https://www.hhs.gov/hipaa/for-individuals/medical-records/index.html', 'Your state medical licensing board -- see jurisdiction table | HHS Office for Civil Rights (records access): 800-368-1019', 'HIPAA right of access (45 CFR 164.524) | Emergency Medical Treatment and Labor Act (42 U.S.C. sec. 1395dd) | National Practitioner Data Bank (42 U.S.C. sec. 11101 et seq.) | State medical malpractice and certificate-of-merit statutes.', 'VERIFIED', '2026-08-17', 'REQUEST THE FULL RECORD INCLUDING THE ELECTRONIC AUDIT TRAIL, AND DO IT NOW. Records requests are cheap, fast, and independent of whether you ever file suit -- and the audit trail is routinely the most probative document in the file. Separately: an EMTALA violation (patient turned away, inadequately screened, or improperly transferred from an emergency department) is reportable to CMS and does not require an attorney or a malpractice claim to pursue. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d14a96214a10b7058899bbaf264d0dee51f11dc4ec5aadf44c3fd9455a56e186]', 'v1.0'),
('SAIS-PC-004', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_workplace_discrimination', 'federal + state', 'federal + state -- ALL_STATES', 'Workplace Discrimination -- Charge Filing, Deferral States, and Right to Sue', 'federal_agency | state_civil_rights_agency', 'personal_crisis_workplace_discrimination', 'https://www.eeoc.gov/filing-charge-discrimination', 'EEOC: 800-669-4000 | TTY 800-669-6820 | Your state fair employment practices agency -- see jurisdiction table', 'Title VII (42 U.S.C. sec. 2000e et seq.) | ADEA (29 U.S.C. sec. 621 et seq.) | ADA Title I (42 U.S.C. sec. 12111 et seq.) | Equal Pay Act (29 U.S.C. sec. 206(d)) | GINA (42 U.S.C. sec. 2000ff) | Rehabilitation Act sec. 501/504.', 'VERIFIED', '2026-08-17', 'FILE WITH THE STATE AGENCY AND EEOC BOTH -- in deferral states the agencies cross-file automatically, but state law frequently offers longer deadlines, broader protected categories, and remedies with no damages cap where federal law imposes one. Checking only the federal box can forfeit the better claim. Also: retaliation is independently actionable, so an adverse action taken AFTER you complain restarts a fresh 180/300-day clock of its own. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 98ad366123d7b17aab78861e999d1ae863d306942060e0db9f5617fa368c7b30]', 'v1.0'),
('SAIS-PC-005', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_consumer_fraud', 'federal + state', 'federal + state -- ALL_STATES', 'Consumer Fraud -- Unfair and Deceptive Acts and Practices', 'federal_agency | state_attorney_general', 'personal_crisis_consumer_fraud', 'https://reportfraud.ftc.gov/', 'FTC Consumer Response Center: 877-382-4357 | CFPB: 855-411-2372 | Your state AG consumer protection division -- see jurisdiction table', 'FTC Act sec. 5 (15 U.S.C. sec. 45) | Truth in Lending Act (15 U.S.C. sec. 1601 et seq.) | Fair Credit Billing Act (15 U.S.C. sec. 1666) | FTC Cooling-Off Rule (16 CFR 429) | Telemarketing Sales Rule (16 CFR 310) | State UDAP statutes.', 'VERIFIED', '2026-08-17', 'PLEAD THE STATE UDAP STATUTE, NOT COMMON-LAW FRAUD, WHERE BOTH ARE AVAILABLE. UDAP typically requires no proof of intent and typically carries fee-shifting and damages multipliers that make representation obtainable. Also check whether a mandatory arbitration clause exists in the contract -- if so, many companies must pay the arbitration filing fees, and mass individual arbitration is a real and underused route. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: a330d5c2cd84f596f3d68c6465759288898c63a38b219a39f4ccf3490448e01f]', 'v1.0'),
('SAIS-PC-006', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_auto_insurance_dispute', 'state', 'state -- ALL_STATES', 'Auto Insurance Dispute -- Coverage You Paid For and May Not Know You Have', 'state_regulator | insurance_carrier', 'personal_crisis_auto_insurance_dispute', 'https://content.naic.org/consumer.htm', 'Your state Department of Insurance -- see jurisdiction table below | NAIC consumer portal', 'McCarran-Ferguson Act (15 U.S.C. sec. 1011) | State unfair claims settlement practices acts (modeled on the NAIC Unfair Claims Settlement Practices Act) | State total-loss and appraisal regulations.', 'VERIFIED', '2026-08-17', 'ASK FOR THE TOTAL LOSS VALUATION REPORT AND THE UM/UIM DECLARATIONS PAGE IN THE SAME WRITTEN REQUEST. Those two documents resolve or reframe the majority of auto disputes. Separately, most states have an unfair claims settlement practices act imposing affirmative duties on adjusters -- prompt acknowledgment, prompt investigation, a written explanation of any denial with reference to the specific policy provision. Adjuster conduct that violates those duties is independently reportable even if the coverage question is genuinely close. [address_resolution: Resolve via the state Department of Insurance office directory; input = state. Larger states operate consumer service offices in multiple cities.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 719e768d3caf057f5c1a241d52e429cd907aa29875b2d1d6cc7a14a8c928b4d8]', 'v1.0'),
('SAIS-PC-007', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_homeowner_insurance', 'state', 'state -- ALL_STATES', 'Homeowner and Property Insurance -- Proof of Loss and the Scope Fight', 'state_regulator | insurance_carrier', 'personal_crisis_homeowner_insurance', 'https://www.fema.gov/flood-insurance/appeal', 'Your state Department of Insurance -- see jurisdiction table below | FEMA (flood/NFIP): 800-621-3362', 'National Flood Insurance Act (42 U.S.C. sec. 4001 et seq.) | NFIP claims and appeals (44 CFR Part 62) | State unfair claims settlement practices acts | State bad-faith statutes and common law.', 'VERIFIED', '2026-08-17', 'COMPLETE AND DOCUMENT REPAIRS BEFORE THE REPLACEMENT-COST HOLDBACK DEADLINE EXPIRES. The recoverable depreciation withheld from the first payment is real money that is forfeited on a schedule most policyholders never read. Also: photograph and inventory everything BEFORE any mitigation or demolition, and keep all damaged materials where safe to do so -- the insurer''s scope position is very hard to rebut once the evidence has been hauled away. [address_resolution: Resolve via the state Department of Insurance office directory; input = state. Larger states operate consumer service offices in multiple cities.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4a84564ed9afd7c3bc828a29ece58f92b570dbefbb8307e24f1e8bc928d03c2e]', 'v1.0'),
('SAIS-PC-008', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_life_insurance_dispute', 'state', 'state -- ALL_STATES', 'Life Insurance Dispute -- Beneficiary Denials and the Two-Year Contestability Window', 'state_regulator | state_unclaimed_property', 'personal_crisis_life_insurance_dispute', 'https://eapps.naic.org/life-policy-locator/', 'NAIC Life Insurance Policy Locator (free) | Your state Department of Insurance -- see jurisdiction table | Your state unclaimed property office', 'State insurance codes and incontestability statutes (based on the NAIC Standard Nonforfeiture and Standard Policy Provisions models) | ERISA (29 U.S.C. sec. 1001 et seq.) for employer group life | State unclaimed property acts.', 'VERIFIED', '2026-08-17', 'RUN THE NAIC POLICY LOCATOR AND SEARCH EVERY STATE''S UNCLAIMED PROPERTY DATABASE BEFORE CONCLUDING NO POLICY EXISTS. Both are free, both take minutes, and unclaimed life benefits are one of the largest categories of escheated property in the country. If the death occurred more than two years after the policy issued, say so explicitly in the first sentence of the appeal -- incontestability is a complete answer to most application-based rescissions and is frequently not raised by the beneficiary. [address_resolution: Resolve via the state Department of Insurance office directory; input = state. Larger states operate consumer service offices in multiple cities.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 40391eef45b59980549c3fede131cd2b637ff99c7ac360f8ddbe7c7992139a08]', 'v1.0'),
('SAIS-PC-009', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_product_liability', 'federal + state', 'federal + state -- ALL_STATES', 'Product Liability -- Preserving the Product and Proving the Defect', 'federal_agency | state_court', 'personal_crisis_product_liability', 'https://www.saferproducts.gov/', 'Consumer Product Safety Commission: 800-638-2772 | NHTSA Vehicle Safety Hotline: 888-327-4236 | FDA MedWatch: 800-332-1088', 'Consumer Product Safety Act (15 U.S.C. sec. 2051 et seq.) | National Traffic and Motor Vehicle Safety Act (49 U.S.C. sec. 30101 et seq.) | Federal Food, Drug, and Cosmetic Act (21 U.S.C. sec. 301 et seq.) | Restatement (Third) of Torts: Products Liability | State product liability statutes.', 'VERIFIED', '2026-08-17', 'PRESERVE THE PRODUCT. EVERYTHING ELSE IS RECOVERABLE; THE PRODUCT USUALLY IS NOT. Then search the CPSC, NHTSA, and FDA public databases for the same model before doing anything else -- prior complaints establish that the manufacturer knew, which converts a defect case into a notice case and substantially changes its value. Note that a manufacturer''s compliance with a federal safety standard is generally a floor, not a defense, in most states. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ea299daf65a48b0eadcdd471448ba8866e683c2114054c20ccd8757497d798c0]', 'v1.0'),
('SAIS-PC-010', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_identity_theft', 'federal', 'federal -- NATIONWIDE', 'Identity Theft -- The Federal Blocking Right Most Victims Never Invoke', 'federal_agency | credit_reporting_agency', 'personal_crisis_identity_theft', 'https://www.identitytheft.gov/', 'FTC Identity Theft Hotline: 877-438-4338 | Annual Credit Report: 877-322-8228 | SSA Fraud Hotline: 800-269-0271 | IRS Identity Protection: 800-908-4490', 'Fair Credit Reporting Act (15 U.S.C. sec. 1681 et seq.) | Identity theft block provision (15 U.S.C. sec. 1681c-2) | Business records disclosure (15 U.S.C. sec. 1681g(e)) | Identity Theft and Assumption Deterrence Act (18 U.S.C. sec. 1028) | Fair and Accurate Credit Transactions Act.', 'VERIFIED', '2026-08-17', 'USE THE BLOCKING RIGHT, NOT THE ORDINARY DISPUTE PROCESS. Most victims file a routine dispute, the furnisher ''verifies'' the debt, and the item stays. The identity theft block under 15 U.S.C. sec. 1681c-2 is mandatory and operates in 4 business days. It requires the FTC Identity Theft Report, which is why obtaining that report is the first step and not an optional one. Also file a police report -- some creditors require it even though federal law does not. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4810d0644d93b325ae45fcc993b6e6d358dfa2d1b891bb9167dcee66980644dc]', 'v1.0'),
('SAIS-PC-011', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_debt_collection_harassment', 'federal + state', 'federal + state -- ALL_STATES', 'Debt Collection Harassment -- The 30-Day Validation Window', 'federal_agency | state_attorney_general', 'personal_crisis_debt_collection_harassment', 'https://www.consumerfinance.gov/complaint/', 'CFPB: 855-411-2372 | FTC: 877-382-4357 | Your state AG consumer protection division -- see jurisdiction table', 'Fair Debt Collection Practices Act (15 U.S.C. sec. 1692 et seq.) | Regulation F (12 CFR Part 1006) | Fair Credit Reporting Act (15 U.S.C. sec. 1681) | Telephone Consumer Protection Act (47 U.S.C. sec. 227) | State debt collection and UDAP statutes.', 'VERIFIED', '2026-08-17', 'NEVER IGNORE A SUMMONS AND NEVER MAKE A GOODWILL PAYMENT ON AN OLD DEBT BEFORE CHECKING THE STATUTE OF LIMITATIONS. In several states a single partial payment or written acknowledgment restarts the entire limitations period on a debt that was already unenforceable. Answering the lawsuit -- even with a simple denial and a demand for proof of ownership of the debt -- defeats most collection suits outright, because the plaintiff frequently cannot produce the chain of assignment. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4dcb709dd0d64eeef9bc356eacbd7692b042acaedea3849ba7fafefa361e5663]', 'v1.0'),
('SAIS-PC-012', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_lemon_law', 'federal + state', 'federal + state -- ALL_STATES', 'Lemon Law and Vehicle Defects -- State Presumptions and the Federal Backstop', 'state_attorney_general | manufacturer_arbitration', 'personal_crisis_lemon_law', 'https://www.nhtsa.gov/report-a-safety-problem', 'NHTSA Vehicle Safety Hotline: 888-327-4236 | BBB AUTO LINE: 800-955-5100 | Your state AG consumer protection division -- see jurisdiction table', 'Magnuson-Moss Warranty Act (15 U.S.C. sec. 2301 et seq.) | UCC Article 2 warranty provisions | National Traffic and Motor Vehicle Safety Act (49 U.S.C. sec. 30101 et seq.) | FTC Used Car Rule (16 CFR Part 455) | State lemon law statutes.', 'VERIFIED', '2026-08-17', 'GET A WRITTEN REPAIR ORDER EVERY SINGLE VISIT AND READ IT BEFORE LEAVING THE DEALERSHIP. The repair order is the entire evidentiary basis of a lemon law claim, and ''could not duplicate'' entries that do not record your reported symptom are the most common reason a qualifying vehicle fails to qualify on paper. If the state lemon law window has closed, do not stop -- Magnuson-Moss and UCC warranty claims commonly run four years and carry attorney fee-shifting. [address_resolution: Resolve via the state AG office directory; input = state. Consumer protection and Medicaid Fraud Control units commonly have separate intake addresses from the main office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: b769b521c734801f0a71173dd5d73a464c7bc991e22f3e7175aef89cd9687e9c]', 'v1.0'),
('SAIS-PC-013', 'systemic_abuse_intelligence', 28, 'personal_crisis', 'personal_crisis_personal_injury', 'state', 'state -- ALL_STATES', 'Personal Injury -- Limitations Periods, Government Notice, and Medical Liens', 'state_court | legal_aid | state_bar_referral', 'personal_crisis_personal_injury', 'https://www.americanbar.org/groups/legal_services/flh-home/', 'Your state bar lawyer referral service -- see jurisdiction table | ABA free legal answers | Dial 211 for local legal aid', 'Federal Tort Claims Act (28 U.S.C. sec. 1346(b), 2671-2680) | Medicare Secondary Payer Act (42 U.S.C. sec. 1395y(b)) | ERISA plan subrogation (29 U.S.C. sec. 1132) | State tort claims acts and notice-of-claim statutes.', 'VERIFIED', '2026-08-17', 'DETERMINE ON DAY ONE WHETHER ANY POTENTIAL DEFENDANT IS A GOVERNMENT ENTITY. The notice-of-claim deadline is the single most common reason a valid injury claim is permanently lost, it can be as short as 30 days, and it runs while the injured person is still in the hospital. Send a written video-preservation demand the same week -- surveillance footage is the most decisive and most perishable evidence in premises and vehicle cases. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e5d3ef29bc8a958efdf520e779b50c4478a68b9fe31fe3c40a15648d5921785f]', 'v1.0')
